// --------------------------------------------------------------------------------------------------
// Détection des termes dans un texte (corrections, fiches)
// --------------------------------------------------------------------------------------------------
const echapperRe = (s) => s.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');
const AVANT = '(?<![\\p{L}\\p{N}_])';
const APRES = '(?![\\p{L}\\p{N}_])';

const DETECTEURS = GLOSSAIRE.map((e) => {
  if (e.re) return { e, re: new RegExp(e.re, 'u') };
  const sensibles = new Set([...(e.cs ? [e.t] : []), ...(e.csv || [])]);
  const formes = [e.t, ...(e.v || [])];
  const motif = (formes) => formes.map((f) => `${echapperRe(f)}(?:s|es)?`).join('|');
  const souples = formes.filter((f) => !sensibles.has(f));
  const strictes = formes.filter((f) => sensibles.has(f));
  const parties = [];
  if (souples.length) parties.push(new RegExp(`${AVANT}(?:${motif(souples)})${APRES}`, 'iu'));
  if (strictes.length) parties.push(new RegExp(`${AVANT}(?:${motif(strictes)})${APRES}`, 'u'));
  return { e, parties };
});

// Termes du lexique présents dans un texte, dans l'ordre de leur première apparition
export function termesDans(texte) {
  const trouves = [];
  for (const d of DETECTEURS) {
    let position = -1;
    if (d.re) { const m = d.re.exec(texte); if (m) position = m.index; }
    else for (const re of d.parties) { const m = re.exec(texte); if (m && (position < 0 || m.index < position)) position = m.index; }
    if (position >= 0) trouves.push({ ...d.e, position });
  }
  return trouves.sort((a, b) => a.position - b.position);
}

export const lexiqueTrie = () => [...GLOSSAIRE].sort((a, b) => a.t.localeCompare(b.t, 'fr', { sensitivity: 'base' }));
